-- ─── G2. Point the district rows at their polygons (Alhambra, Carson: mtfcc was NULL; Monterey Park: the
--        city's own 2026 polygons were loaded as X0001 but the rows still said G4110) ─────────────
UPDATE essentials.districts d SET mtfcc = 'X0001'
 WHERE d.district_type = 'LOCAL' AND d.mtfcc IS DISTINCT FROM 'X0001'
   AND (d.geo_id LIKE 'alhambra-council-district-_' OR d.geo_id LIKE 'carson-council-district-_'
        OR d.geo_id LIKE 'ocd-division/country:us/state:ca/place:monterey_park/ward:_');

-- ─── G3. Monterey Park elected City Clerk + City Treasurer (the Carson pattern: own chamber, LOCAL_EXEC office) ──
INSERT INTO essentials.chambers (id, government_id, name, name_formal, policy_engagement_level)  -- slug is generated
SELECT v.id, 'c087cd55-b5d5-4062-a439-44605ea1c65b'::uuid, v.name, v.name_formal, 'full' FROM (VALUES
    ('cddfa23d-5d1a-454b-acbc-7a1a6c5c8e22'::uuid, 'City Clerk', 'Monterey Park City Clerk'),
    ('325a1924-90a8-4784-8765-deb8146cfd5c'::uuid, 'City Treasurer', 'Monterey Park City Treasurer')
  ) AS v(id, name, name_formal) WHERE NOT EXISTS (SELECT 1 FROM essentials.chambers c WHERE c.id = v.id);
INSERT INTO essentials.offices (id, chamber_id, district_id, title, representing_state, seats, normalized_position_name,
