-- ─── 0. Pre-flight: every binding target exists ───────────────────────────────────────
DO $$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM (VALUES
    ('alhambra-council-district-1', 'LOCAL', NULL, 'Alhambra City Council District 1'),
    ('alhambra-council-district-2', 'LOCAL', NULL, 'Alhambra City Council District 2'),
    ('alhambra-council-district-5', 'LOCAL', NULL, 'Alhambra City Council District 5'),
    ('carson-council-district-2', 'LOCAL', NULL, 'Carson City Council District 2'),
    ('carson-council-district-4', 'LOCAL', NULL, 'Carson City Council District 4'),
    ('0611530', 'LOCAL_EXEC', 'City Clerk', 'Carson City Clerk'),
    ('0611530', 'LOCAL_EXEC', 'City Treasurer', 'Carson City Treasurer'),
    ('ocd-division/country:us/state:ca/place:monterey_park/ward:1', 'LOCAL', NULL, 'Monterey Park City Council District 1'),
    ('ocd-division/country:us/state:ca/place:monterey_park/ward:5', 'LOCAL', NULL, 'Monterey Park City Council District 5'),
    ('0648914', 'LOCAL_EXEC', 'City Clerk', 'Monterey Park City Clerk'),
    ('0648914', 'LOCAL_EXEC', 'City Treasurer', 'Monterey Park City Treasurer')
  ) AS v(place, dtype, otitle, pos)
   WHERE NOT EXISTS (SELECT 1 FROM essentials.offices o JOIN essentials.districts d ON d.id = o.district_id
                      WHERE d.geo_id = v.place AND d.district_type = v.dtype AND (v.otitle IS NULL OR o.title = v.otitle));
  IF n <> 0 THEN RAISE EXCEPTION 'pre-flight: % race(s) with no office to bind to', n; END IF;
END $$;

-- ─── 1. Races ─────────────────────────────────────────────────────────────────────────
INSERT INTO essentials.races (election_id, office_id, position_name, primary_party, seats)
SELECT 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid, t.office_id, t.pos, NULL, t.seats
  FROM (SELECT v.pos, v.seats,
               (SELECT o.id FROM essentials.offices o JOIN essentials.districts d ON d.id = o.district_id
                 WHERE d.geo_id = v.place AND d.district_type = v.dtype AND (v.otitle IS NULL OR o.title = v.otitle)
                 ORDER BY o.id LIMIT 1) AS office_id
          FROM (VALUES
    ('alhambra-council-district-1', 'LOCAL', NULL, 'Alhambra City Council District 1', 1),
    ('alhambra-council-district-2', 'LOCAL', NULL, 'Alhambra City Council District 2', 1),
    ('alhambra-council-district-5', 'LOCAL', NULL, 'Alhambra City Council District 5', 1),
    ('carson-council-district-2', 'LOCAL', NULL, 'Carson City Council District 2', 1),
    ('carson-council-district-4', 'LOCAL', NULL, 'Carson City Council District 4', 1),
    ('0611530', 'LOCAL_EXEC', 'City Clerk', 'Carson City Clerk', 1),
    ('0611530', 'LOCAL_EXEC', 'City Treasurer', 'Carson City Treasurer', 1),
    ('ocd-division/country:us/state:ca/place:monterey_park/ward:1', 'LOCAL', NULL, 'Monterey Park City Council District 1', 1),
    ('ocd-division/country:us/state:ca/place:monterey_park/ward:5', 'LOCAL', NULL, 'Monterey Park City Council District 5', 1),
    ('0648914', 'LOCAL_EXEC', 'City Clerk', 'Monterey Park City Clerk', 1),
    ('0648914', 'LOCAL_EXEC', 'City Treasurer', 'Monterey Park City Treasurer', 1)
          ) AS v(place, dtype, otitle, pos, seats)) t
 WHERE t.office_id IS NOT NULL
   AND NOT EXISTS (SELECT 1 FROM essentials.races r WHERE r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND r.position_name = t.pos);

